with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('gå agurk', 'phrase', '9cb86693-bd4c-5425-bdc3-019f19815935', 1, 'verb', null, 'збожеволіти', 'Min gamle computer gik agurk i går.', 'Мій старий комп''ютер вчора збожеволів.'), ('gå itu', 'phrase', 'ef2d9a0b-06f3-5bd1-9af9-326f5843b457', 1, 'verb', null, 'розбиватися', 'Min telefon gik itu, da jeg tabte den på gulvet.', 'Мій телефон зламався, коли я впустив його на підлогу.'), ('ombestemme sig', 'phrase', '4a9627c8-cec7-570e-a689-93cccfb9ad50', 1, 'verb', null, 'передумати', 'Jeg tror, at han ombestemmer sig i morgen.', 'Думаю, завтра він змінить свою думку.'), ('slå plat og krone', 'phrase', '95d4ca0e-cc3d-501e-be8a-5531d1e03419', 1, 'verb', null, 'підкидати монету (щоб щось вирішити)', 'Vi slog plat og krone om den sidste kage.', 'Ми підкинули монетку, щоб вирішити, кому дістанеться останній шматок торта.'), ('gå for sig', 'phrase', '6b919881-6e45-5ee1-aa2b-f0c189cabae8', 1, 'verb', null, 'відбуватися', 'Mødet gik for sig i kantinen.', 'Зустріч відбулася в їдальні.'), ('gøre godt', 'phrase', '2810693d-fd4f-539a-81ec-6452e84e3835', 1, 'verb', null, 'приносити користь', 'Motion gør godt for helbredet.', 'Фізичні вправи корисні для здоров''я.'), ('se sig for', 'phrase', '24e790b4-1e18-5894-9c32-d785a3563645', 1, 'verb', null, 'дивитися навкруги (бути обережним)', 'Du skal se dig for, når du går over gaden.', 'Треба бути обережним, коли переходиш вулицю.'), ('se sig om', 'phrase', '05d1af47-17eb-5651-8fb3-dd720b093467', 1, 'verb', null, 'озиратися (навколо)', 'Hun ser sig om i det nye hus.', 'Вона оглядає новий будинок.'), ('se op', 'phrase', '8b368b3a-537a-5412-8720-f29b2b878ae1', 1, 'verb', null, 'дивитися вгору', 'Hun ser op mod himlen.', 'Вона дивиться вгору на небо.'), ('se op til', 'phrase', '90ccf80c-2d6c-5aeb-8527-ea952ad80efc', 1, 'verb', null, 'захоплюватися (кимось)', 'Mange børn ser op til deres forældre.', 'Багато дітей захоплюються своїми батьками.'), ('tage for sig', 'phrase', '99883457-5da0-5256-ac56-e6a34d99b5b0', 1, 'verb', null, 'брати собі (їжу)', 'Tag for dig af salaten, der er nok.', 'Пригощайся салатом, його достатньо.'), ('tage over', 'phrase', '6a777937-db71-56ad-b196-08acafce9bba', 1, 'verb', null, 'брати на себе (управління, відповідальність)', 'Hun tager over, når chefen er syg.', 'Вона бере на себе керівництво, коли бос хворий.'), ('tage sig for', 'phrase', '82e28e56-784f-563b-b60c-24ce93dab675', 1, 'verb', null, 'займатися (чимось)', 'Hvad vil du tage dig for i weekenden?', 'Чим ти займешся на вихідних?'), ('blive stående', 'phrase', '68610d24-abc2-501f-a93a-e8aa7a6bf831', 1, 'verb', null, 'залишатися стояти', 'Han blev stående ved døren i lang tid.', 'Він залишався стояти біля дверей довгий час.'), ('stå godt til', 'phrase', '0e429d81-495c-51dc-a6c6-3f332f244f3e', 1, 'verb', null, 'бути в хорошому стані (про справи, стосунки)', 'Det står godt til med deres ægteskab.', 'З їхнім шлюбом усе добре.'), ('sige sig selv', 'phrase', '05c59836-9e5f-5a5d-b793-ef97817c7827', 1, 'verb', null, 'само собою зрозуміло', 'Det siger sig selv, at børn har brug for kærlighed.', 'Само собою зрозуміло, що дітям потрібна любов.'), ('være lige ved at', 'phrase', '8a2af559-f4f7-5811-be3c-0c3143b61850', 1, 'verb', null, 'бути на межі (чогось)', 'Jeg var lige ved at falde på isen.', 'Я мало не впав на лід.'), ('gøre brug af', 'phrase', 'dea966c5-d759-5956-8af0-dfc46bd6e2b7', 1, 'verb', null, 'використовувати', 'Hun gør brug af sin erfaring i det nye job.', 'Вона використовує свій досвід на новій роботі.'), ('dele sig op', 'phrase', '2e0e0abe-61d5-5e0c-9af1-73b5701c1248', 1, 'verb', null, 'розділятися (на групи)', 'Eleverne deler sig op i mindre grupper til projektarbejde.', 'Учні діляться на менші групи для роботи над проєктом.'), ('holde til', 'phrase', '375a0d0e-8c6c-5ec7-8fb5-84f405832a47', 1, 'verb', null, 'знаходитися, перебувати', 'Mange unge holder til i parken om sommeren.', 'Багато молодих людей проводять час у парку влітку.'), ('holde til', 'phrase', '6548b6c7-d0a6-573a-9718-90e2ef6d331a', 2, 'verb', null, 'витримувати, терпіти', 'Jeg kan ikke holde til al den støj længere.', 'Я більше не можу терпіти весь цей шум.'), ('holde ved', 'phrase', 'b94ff8ae-da70-5c34-8d4e-114cba7872d9', 1, 'verb', null, 'продовжувати (робити щось)', 'Hun holdt ved med at øve sig hver dag.', 'Вона продовжувала тренуватися щодня.'), ('blive et nyt menneske', 'phrase', 'f63beced-6a8f-529c-b5a9-e3941241e3fc', 1, 'verb', null, 'стати іншою людиною (змінитися на краще)', 'Efter rejsen føler jeg, at jeg er blevet et nyt menneske.', 'Після поїздки я відчуваю, що став новою людиною.'), ('se sig tilbage', 'phrase', 'f842ed24-2bc2-5369-8cf8-dd622df3834a', 1, 'verb', null, 'оглядатися назад', 'Hun så sig tilbage, før hun gik ind i huset.', 'Вона озирнулася, перш ніж увійти в будинок.'), ('veje op', 'phrase', 'ef6e0707-f394-52e5-861f-c5be1c64ea36', 1, 'verb', null, 'компенсувати (недолік)', 'Hans erfaring vejer op for den manglende uddannelse.', 'Його досвід компенсує відсутність освіти.'), ('skrive ned', 'phrase', '34c8e248-f056-5531-8585-d4cd942275a1', 1, 'verb', null, 'записувати', 'Jeg skrev ned hvad læreren sagde.', 'Я записав те, що сказав учитель.'), ('komme til penge', 'phrase', 'a120794d-39b0-5cfd-a72e-f3d4c3c992a2', 1, 'verb', null, 'отримати гроші (несподівано)', 'Han kom til penge, da hans onkel døde.', 'Він отримав гроші, коли помер його дядько.'), ('klare den', 'phrase', '0eed097d-a0d8-52bd-895d-ea8476392839', 1, 'verb', null, 'справлятися', 'Jeg tror, hun klarer den uden hjælp.', 'Я думаю, вона впорається без допомоги.'), ('klare op', 'phrase', '9232b613-c539-5016-8c04-a06ab9988cf2', 1, 'verb', null, 'прояснюватися (про погоду)', 'Det regner nu, men det klarer op senere.', 'Зараз іде дощ, але пізніше проясниться.'), ('være tro mod', 'phrase', '5c833509-a1b3-5d0e-9862-98457a8845fe', 1, 'verb', null, 'бути вірним', 'Han er tro mod sine venner.', 'Він вірний своїм друзям.'), ('lægge sig ned', 'phrase', 'c1713ff9-4d31-591e-80b2-f5803e6024c2', 1, 'verb', null, 'лягати', 'Jeg lægger mig ned på sofaen efter arbejde.', 'Я лягаю на диван після роботи.'), ('begynde med at', 'phrase', '67e53252-5fb9-59cb-9e19-7789aaa9ae28', 1, 'verb', null, 'починати з того, що', 'Jeg begynder med at tage opvasken.', 'Я починаю з миття посуду.'), ('gå på grund', 'phrase', '46599fb2-34d5-5221-8647-0e8d5e3698c6', 1, 'verb', null, 'сісти на мілину (про судно)', 'Skibet gik på grund nær havnen.', 'Корабель сів на мілину біля гавані.'), ('på grund af at', 'phrase', 'a229d558-8ab9-594a-b83f-6e2b452ce05f', 1, 'adverb', null, 'тому що', 'Vi blev hjemme på grund af at det regnede.', 'Ми залишилися вдома, тому що йшов дощ.'), ('gøre kål på', 'phrase', '52898bb9-23db-5b67-9111-2155f21292e6', 1, 'verb', null, 'покінчити з (чимось)', 'Vi gjorde kål på resterne fra i går.', 'Ми доїли вчорашні залишки.'), ('gå sammen', 'phrase', 'eb9af950-d090-5ce5-bd1b-7df1d4c0b7cf', 1, 'verb', null, 'об''єднуватися', 'De to virksomheder gik sammen om et nyt projekt.', 'Обидві компанії об''єднали зусилля над новим проєктом.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'uk'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'uk', text, pos, gender, example, example_translation, 'pipeline-phrases-0011' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
